"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["42217"],{22590(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.cascata_origem_nao_segue_cascata","status":422,"titulo":"A cascata declara origem que nenhuma oferta do processo marca como SegueCascata"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.cascata_origem_nao_segue_cascata","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["A cascata do processo declara, como origem, um c\xf3digo de modalidade que\\nnenhuma oferta do processo marca com `regraRemanejamento` igual a\\n`SEGUE_ORDEM_DE_REMANEJAMENTO`. \xc9 a confer\xeancia inversa de\\n[`cascata_origem_ausente`](/erros/uniplus.selecao.processo_seletivo.cascata_origem_ausente):\\nl\xe1, a modalidade `SEGUE_ORDEM_DE_REMANEJAMENTO` existe mas a cascata n\xe3o a cobre; aqui, a\\ncascata cobre uma origem que nenhuma modalidade `SEGUE_ORDEM_DE_REMANEJAMENTO` de fato\\nusa \u2014 a fila de destinos daquela origem n\xe3o tem para qu\xea existir.","Diferente das causas anteriores desta s\xe9rie, que rodam durante a\\navalia\xe7\xe3o oferta por oferta, esta roda **depois**, numa segunda passada\\nque s\xf3 acontece se nenhuma oferta reprovou nenhuma delas: percorre as\\norigens da cascata, em ordem determin\xedstica, e confere cada uma contra o\\nconjunto de todos os c\xf3digos de modalidade `SEGUE_ORDEM_DE_REMANEJAMENTO` do processo,\\nsomando todas as ofertas. Sequencial: a primeira origem com essa\\ninconsist\xeancia interrompe a avalia\xe7\xe3o; nunca acumula com nenhuma outra\\ncausa desta s\xe9rie, e nunca coexiste com as quatro anteriores \u2014 se alguma\\ndelas tivesse disparado, a avalia\xe7\xe3o j\xe1 teria parado antes de chegar\\naqui."],"comoResolver":["Remova a origem apontada da cascata, ou configure alguma modalidade do\\nprocesso com `remanejamento.regra` igual a `SEGUE_ORDEM_DE_REMANEJAMENTO` e o mesmo c\xf3digo\\ndessa origem."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);